Requirement:
An actor may rename a project only when they belong to its current organization. Moving a project also requires membership in the destination organization.

Code:
export async function updateProject(req: Request, actor: Actor) {
  const project = await projects.get(req.params.projectId);
  if (!project) {
    return response.notFound();
  }

  const destinationOrgId = req.body.organizationId ?? project.organizationId;
  if (!actor.organizationIds.includes(destinationOrgId)) {
    return response.forbidden();
  }

  await projects.update(project.id, {
    name: req.body.name ?? project.name,
    organizationId: destinationOrgId,
  });
  return response.noContent();
}


